 "content": "def transform(grid):
    # Find the 3x3 glyph. Its 2-valued center determines the cross center.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    center = None
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3 for rr, cc in (
                (r-1,c-1), (r-1,c), (r-1,c+1), (r,c-1), (r,c+1),
                (r+1,c-1), (r+1,c), (r+1,c+1))):
                center = (r, c)
                break
        if center is not None:
            break
    if center is None:
        return out
    r, c = center
    # Extend the marker as a cross until the next horizontal/vertical 2-line
    # boundary, recoloring intervening zero cells in the new color.
    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == 2:
                break
            if grid[rr][cc] == 0:
                out[rr][cc] = 1
            rr += dr
            cc += dc
    return out
