 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the 3x3 marker: a central 2 surrounded by eight 3s.
    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in (
                    (r - 1, c - 1), (r - 1, c), (r - 1, c + 1),
                    (r, c - 1),                 (r, c + 1),
                    (r + 1, c - 1), (r + 1, c), (r + 1, c + 1),
                )
            ):
                markers.append((r, c))

    # A continuous 2-line through the marker determines the direction of
    # propagation; the new 1-line goes perpendicular to it.
    for r, c in markers:
        col_rail = sum(grid[rr][c] == 2 for rr in range(h))
        row_rail = sum(grid[r][cc] == 2 for cc in range(w))
        if row_rail > col_rail:
            # Horizontal 2-rail through the marker -> vertical trace.
            trace = [(rr, c) for rr in range(h)]
        else:
            # Vertical 2-rail through the marker -> horizontal trace.
            trace = [(r, cc) for cc in range(w)]

        # Fill the trace through blanks. Every crossed 2-cell becomes the
        # center of a 3x3 crossing patch; retain the center and existing 3s.
        for rr, cc in trace:
            if grid[rr][cc] == 0:
                out[rr][cc] = 1
            elif grid[rr][cc] == 2:
                for r2 in range(max(0, rr - 1), min(h, rr + 2)):
                    for c2 in range(max(0, cc - 1), min(w, cc + 2)):
                        if (r2, c2) != (rr, cc) and grid[r2][c2] != 3:
                            out[r2][c2] = 1
    return out
