    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = []

    # Markers are 3x3 squares of 3s surrounding a central 2.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in (
                    (r - 1, c - 1), (r - 1, c), (r - 1, c + 1),
                    (r, c - 1),                 (r, c + 1),
                    (r + 1, c - 1), (r + 1, c), (r + 1, c + 1),
                )
            ):
                markers.append((r, c))

    # The 2-valued rails determine which way each marker projects its 1-line.
    vertical_rails = [
        c for c in range(w)
        if sum(grid[r][c] == 2 for r in range(h)) >= h // 2
    ]
    horizontal_rails = [
        r for r in range(h)
        if sum(value == 2 for value in grid[r]) >= w // 2
    ]

    for r, c in markers:
        if r in horizontal_rails:
            # A marker centered on a horizontal 2-rail projects vertically.
            trace = [(rr, c) for rr in range(h)]
            crossings = [(hr, c) for hr in horizontal_rails if grid[hr][c] == 2]
        elif c in vertical_rails:
            # A marker centered on a vertical 2-rail projects horizontally.
            trace = [(r, cc) for cc in range(w)]
            crossings = [(r, vc) for vc in vertical_rails if grid[r][vc] == 2]
        else:
            continue

        # Color empty cells along the projected line. At each crossed rail,
